import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';  // Add this line

function Home() {
  const [featuredMeals, setFeaturedMeals] = useState([]);

  useEffect(() => {
    fetchFeaturedMeals();
  }, []);

  const fetchFeaturedMeals = async () => {
    try {
      // Mock data or fetch from backend (extend backend if needed)
      const meals = [
        { name: 'Grilled Veggie Salad', calories: 500, image: 'https://via.placeholder.com/150?text=Veggie+Salad' },
        { name: 'Chicken Stir-Fry', calories: 600, image: 'https://via.placeholder.com/150?text=Chicken+Stir-Fry' },
      ];
      setFeaturedMeals(meals);
    } catch (error) {
      console.error('Failed to fetch featured meals:', error);
    }
  };

  return (
    <div style={{ padding: '20px', textAlign: 'center' }}>
      <h1>Welcome to MealMind</h1>
      <p>Discover delicious, personalized meal plans with AI-powered suggestions!</p>
      <div style={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: '20px', marginTop: '20px' }}>
        {featuredMeals.map((meal, index) => (
          <div key={index} style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '8px', width: '150px' }}>
            <img src={meal.image} alt={meal.name} style={{ width: '100%', borderRadius: '4px' }} />
            <h3>{meal.name}</h3>
            <p>{meal.calories} kcal</p>
          </div>
        ))}
      </div>
      <p style={{ marginTop: '20px' }}>
        <Link to="/signin" style={{ color: '#007BFF', textDecoration: 'none' }}>Sign in</Link> to explore more features!
      </p>
    </div>
  );
}

export default Home;
